import { createRouter } from '@tanstack/react-router'
import { routeTree } from './routeTree.gen'
import { queryClient } from './lib/query'

// Router instance (performance-plan.md 4.6). routeTree.gen.ts is generated by the router plugin
// / `npm run routes` — never edit it by hand; on a merge conflict regenerate it.

export const router = createRouter({
  routeTree,
  context: { queryClient },
  // touch/hover/focus on a link → load its chunk (and loader) early. The delay applies to hover and
  // focus only: TanStack preloads on touchstart at once. The feed cards (a scrolling list) therefore
  // opt out and preload on hover/focus only (features/feed/useIntentPreload.ts).
  defaultPreload: 'intent',
  defaultPreloadDelay: 50,
  defaultPreloadStaleTime: 0, // data freshness is TanStack Query's job, not the router cache's
  defaultPendingMs: 150, // show a route skeleton only after 150 ms …
  defaultPendingMinMs: 300, // … and then for at least 300 ms (no flicker)
  defaultViewTransition: true, // feed ↔ occasion shared-element transition (pilot-decisions §7); no-op where unsupported
  scrollRestoration: true,
  // The dev phone frame scrolls its own element, not the window: a new screen starts at the top
  // there too. No such element in production, so this is a no-op outside the dev frame.
  scrollToTopSelectors: ['.pf-app'],
})

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
  interface StaticDataRouteOption {
    /** a route under _authed that must work before the consent records exist (/welcome/profile) */
    allowWithoutConsent?: boolean
    /**
     * The shell's legal footer (Impressum · Datenschutz · Nutzungsbedingungen + "Private Testversion · 18+").
     * The deepest route that sets it decides (routes/__root.tsx); default: shown. `_authed` sets false —
     * signed in, the Profil tab's "Rechtliches" section replaces it (pilot-decisions §00.2); the sign-up
     * step /welcome/profile decides by its search (wave 2): shown, except when the Profil tab opened it as
     * "Name ändern" (`?from=profile`). A function gets the match's validated search.
     */
    legalFooter?: boolean | ((search: Record<string, unknown>) => boolean)
  }
}
